  /* Theme ----------------------------------------------------------------- */
  function readStoredTheme() {
    try {
      var value = window.localStorage.getItem(THEME_KEY);
      return value === "light" || value === "dark" ? value : null;
    } catch (error) {
      return null;
    }
  }

  function storeTheme(theme) {
    try {
      window.localStorage.setItem(THEME_KEY, theme);
    } catch (error) {
      /* Storage can be blocked (private mode, file://). The theme still works
         for the current page. */
    }
  }

  var systemTheme = window.matchMedia("(prefers-color-scheme: dark)");

  function effectiveTheme() {
    var explicit = root.getAttribute("data-theme");
    if (explicit === "light" || explicit === "dark") {
      return explicit;
    }
    return systemTheme.matches ? "dark" : "light";
  }

  var storedTheme = readStoredTheme();
  if (storedTheme) {
    root.setAttribute("data-theme", storedTheme);
  }

  function ensureThemeColorMeta() {
    var meta = document.head.querySelector('meta[name="theme-color"]');
    if (!meta) {
      meta = document.createElement("meta");
      meta.setAttribute("name", "theme-color");
      document.head.appendChild(meta);
    }
    meta.setAttribute("content", effectiveTheme() === "dark" ? "#08110F" : "#F6FAF8");
  }

  function ensureFavicon() {
    if (document.head.querySelector('link[rel~="icon"]')) {
      return;
    }
    var link = document.createElement("link");
    link.rel = "icon";
    link.type = "image/svg+xml";
    link.href = assetUrl("img/favicon.svg");
    document.head.appendChild(link);
  }

  function updateThemeControls() {
    var theme = effectiveTheme();
    var isDark = theme === "dark";
    var buttons = document.querySelectorAll("[data-theme-toggle]");

    Array.prototype.forEach.call(buttons, function (button) {
      var use = button.querySelector("use");
      var label = isDark ? "Activar modo claro" : "Activar modo oscuro";
      button.setAttribute("aria-label", label);
      button.setAttribute("title", label);
      if (use) {
        use.setAttribute("href", isDark ? "#icon-sun" : "#icon-moon");
      }
    });

    ensureThemeColorMeta();
  }

  function applyTheme(theme, persist) {
    root.setAttribute("data-theme", theme);
    if (persist) {
      storeTheme(theme);
    }
    updateThemeControls();
    document.dispatchEvent(
      new CustomEvent("pf:themechange", { detail: { theme: theme } })
    );
  }

  /* Markup ---------------------------------------------------------------- */
  var NAV_ITEMS = [
    { label: "Inicio", file: "index.html" },
    { label: "Servicios", file: "servicios.html" },
    { label: "Equipo", file: "equipo.html" },
    { label: "Mis mascotas", file: "mis-mascotas.html" },
    { label: "Contacto", file: "contacto.html" },
    { label: "Agendar cita", file: "agendar.html", cta: true }
  ];

  function currentPage() {
    var parts = window.location.pathname.split("/").filter(Boolean);
    return parts.pop() || "index.html";
  }

  function isCurrentItem(item) {
    if (window.location.pathname.indexOf("/documentacion/") !== -1) {
      return false;
    }
    var page = currentPage().replace(/\.html$/, "");
    var target = item.file.replace(/\.html$/, "");

    if (page === target) {
      return true;
    }
    if (item.file === "servicios.html" && /\/servicios?(\/|\.html$)/.test(window.location.pathname)) {
      return true;
    }
    if (item.file === "agendar.html" && /\/agendar(\/|$)/.test(window.location.pathname)) {
      return true;
    }
    return false;
  }

  function navMarkup() {
    return NAV_ITEMS.map(function (item) {
      var current = isCurrentItem(item) ? ' aria-current="page"' : "";
      var className = item.cta
        ? "btn btn--primary site-nav__cta"
        : "site-nav__link";
      return (
        '<li><a class="' +
        className +
        '" href="' +
        pageUrl(item.file) +
        '"' +
        current +
        ">" +
        item.label +
        "</a></li>"
      );
    }).join("");
  }

